message.content:
{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "tN1rLfoJ8dEPVOKknB3LGg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the ruined city gate.",
      "visual_description": "A shattered iron gate hangs askew, old royal banners torn and faded. Mara studies a brass compass while the glass diver adjusts his helmet. The oracle lamp flickers on a broken wall, its eye scanning the dark.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "The clockwork fox picks its way over cracked stone, tail winding slowly. Its blue eyes reflect faint light from a distant tower.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame eye flares amber. It speaks in whispers while pointing its handle toward a leaning spire wrapped in thorny vines.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector blocks a passage.",
      "visual_description": "A figure in dusty robes snores loudly, head resting on a ledger book. Stamped papers are stuck to his sleeves. The passage behind him is sealed by a magic door pulsing with runes.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "Mara negotiates with the sleeping official.",
      "visual_description": "Mara shakes the tax collector gently. He mumbles and turns over, a paper with a wax emblem fluttering to the floor. The glass diver inspects the magic door.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through the door's reflection.",
      "visual_description": "The glass diver presses his helmet against the door's surface, which ripples like water. He steps through into the mirrored interior, leaving a silvery wake.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Inside the tower, the glass diver finds a secret room.",
      "visual_description": "A circular room lined with cracked mirrors. Dusty light falls from a broken ceiling. The diver's reflection multiplies in every shard.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp guides the team through a maze.",
      "visual_description": "The lamp's flame casts shifting shadows on high walls. Mara follows its glow, the tin fox clicking beside her. The tax collector trudges behind, still half-asleep.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "They encounter a hall of floating banners.",
      "visual_description": "Old royal banners hang from nowhere, swaying as if in wind. The tin fox sniffs the air, its tail winding faster. Mara consults her map.",
      "characters": ["tin_fox", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver returns with a clue from the mirror room.",
      "visual_description": "The diver steps out of a tall window-pane, holding a fragment of mirror that shows a different part of the city. He points toward a distant bridge.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols march through the courtyard.",
      "visual_description": "Figures in dark plate armor move in lockstep across cracked paving. Their visors are blank. The team presses against a wall, hiding behind a fallen pillar.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox lures the patrol away.",
      "visual_description": "The tiny fox darts into the open, making clicking sounds. The patrol turns as one and follows it into a side alley. Its blue eyes gleam in the dark.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Frightened townspeople whisper from a boarded window.",
      "visual_description": "Shadows move behind a shuttered window. A thin hand points toward the castle gates. Voices murmur rumors of a beast in the keep.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The team reaches the castle gates.",
      "visual_description": "Two immense doors of black iron, studded with rust. Old royal banners hang above, tattered. The oracle lamp flares nervously.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver opens the gate from inside.",
      "visual_description": "The diver slips through a reflection in a moat puddle, reappears inside the gatehouse, and turns a massive wheel. The gates groan open.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Inside, they find the one they came to rescue.",
      "visual_description": "A figure waits in a crumbling hall, lit by a single shaft of moonlight. The glass diver removes his helmet. Mara steps forward, compass in hand.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The escape across the bridge begins.",
      "visual_description": "A narrow stone bridge arcs over a dark chasm. The team runs, the oracle lamp casting long shadows. Behind them, the city groans as towers collapse.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge holds as they cross to safety.",
      "visual_description": "The last stone of the bridge crumbles behind them. On the far side, the team looks back at the ruined city. The oracle lamp's flame steadies. Dawn breaks over the horizon.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

